		state.listeners.get('message')?.('example.test', JSON.stringify({ channel: 'internal', message: { type: 'webhookUpdated', body: { ...hook, active: false } } }));
		release([hook]);
		await pending;
		await hooks.enqueue('owner', 'note', {});
		expect(enqueue).toHaveBeenCalledTimes(1);
	} finally {
		release([]);
		await hooks.close();
	}
});

